#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const fsp = fs.promises;
const args = process.argv.slice(2);
let beforeDateStr = null;
let dir = 'logs';
for (let i = 0; i < args.length; i++) {
  const a = args[i];
  if (a === '--before' && i + 1 < args.length) beforeDateStr = args[++i];
  else if (a === '--dir' && i + 1 < args.length) dir = args[++i];
}
function isValidDate(str) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(str)) return false;
  const d = new Date(str);
  return d && d.toISOString().startsWith(str);
}
if (!beforeDateStr || !isValidDate(beforeDateStr)) {
  process.exit(2);
}
const beforeDate = new Date(beforeDateStr);
const archiveBase = path.join(dir, 'archive');
const manifestPath = path.join(archiveBase, 'manifest.json');
async function main() {
  const files = await fsp.readdir(dir);
  const moves = [];
  for (const f of files) {
    const m = f.match(/^app-(\d{4}-\d{2}-\d{2})\.log$/);
    if (!m) continue;
    const fileDateStr = m[1];
    const fileDate = new Date(fileDateStr);
    if (fileDate < beforeDate) {
      const month = fileDateStr.slice(0, 7);
      const destDir = path.join(archiveBase, month);
      const srcPath = path.join(dir, f);
      const destPath = path.join(destDir, f);
      await fsp.mkdir(destDir, { recursive: true });
      await fsp.rename(srcPath, destPath);
      moves.push({ file: f, to: `archive/${month}/${f}` });
    }
  }
  if (moves.length) {
    let manifest = { moved: [] };
    try {
      const data = await fsp.readFile(manifestPath, 'utf8');
      manifest = JSON.parse(data);
      if (!Array.isArray(manifest.moved)) manifest.moved = [];
    } catch { }
    manifest.moved.push(...moves);
    await fsp.mkdir(archiveBase, { recursive: true });
    await fsp.writeFile(manifestPath, JSON.stringify(manifest, null, 2), 'utf8');
  }
}
main().catch(err => { console.error(err); process.exit(1); });

