// csv.mjs
export function parseCsv(text){
  // Remove UTF-8 BOM if present
  if(text.startsWith('\uFEFF')) text=text.slice(1);
  const lines=text.split(/\r?\n/);
  const records=[];
  let physicalLine=0;
  for(const raw of lines){
    physicalLine++;
    if(raw===''||raw===undefined) continue; // skip empty line
    let i=0;
    const fields=[];
    let field='';
    let inQuotes=false;
    let startFieldLine=physicalLine;
    while(i<raw.length){
      const c=raw[i];
      if(inQuotes){
        if(c==='\"'){
          if(i+1<raw.length && raw[i+1]==='\"'){
            field+='\"'; i++; // escaped quote
          } else {
            inQuotes=false;
          }
        } else {
          field+=c;
        }
      } else {
        if(c===','){
          fields.push(field); field='';
        } else if(c==='\"'){
          if(field.length===0){
            inQuotes=true; startFieldLine=physicalLine;
          } else {
            throw new Error(`CSV line ${physicalLine}: unexpected quote`);
          }
        } else {
          field+=c;
        }
      }
      i++;
    }
    if(inQuotes){
      throw new Error(`CSV line ${startFieldLine}: unterminated quoted field`);
    }
    fields.push(field);
    records.push(fields);
  }
  return records;
}

export function exportCsv(tasks){
  const headers=['id','title','priority','status','due','tags','notes','created','completed'];
  const escapeQuote=str=>str.replace(/\"/g, '\"\"');
  const quoteEscape=str=>{ if(/[\",\r\n]/.test(str)||/^ | $/.test(str)) return `\"${escapeQuote(str)}\"`; return str; };
  const sanitizer=val=>{ const s=String(val||''); if(/^([=+\-@])/.test(s)) return `'${s}`; return s; };
  const rows=[headers.join(',')];
  for(const t of tasks){
    const row=header=>{switch(header){case 'id': return sanitizer(t.id);case 'title': return quoteEscape(sanitizer(t.title));case 'priority': return sanitizer(t.priority||'normal');case 'status': return sanitizer(t.status);case 'due': return sanitizer(t.due||'');case 'tags': return sanitizer(t.tags?.join(';')||'');case 'notes': return quoteEscape(sanitizer(t.notes||''));case 'created': return sanitizer(t.created);case 'completed': return sanitizer(t.completed||'');default: return '';}}
    const fields=headers.map(h=>row(h));
    rows.push(fields.join(','));
  }
  return rows.join('\n')+'\n';
}

import assert from 'assert';
import {parseCsv, exportCsv} from '../src/csv.mjs';

describe('CSV parsing', () => {
  it('parses simple CSV', () => {
    const csv = 'a,b,c\n1,2,3';
    const rec = parseCsv(csv);
    assert.deepStrictEqual(rec, [['a','b','c'],['1','2','3']]);
  });
  it('skips empty line', () => {
    const csv = 'x,y\n\n1,2';
    const rec = parseCsv(csv);
    assert.deepStrictEqual(rec, [['x','y'],['1','2']]);
  });
  it('handles quoted fields', () => {
    const csv = 'a,"b,comma",c';
    const rec = parseCsv(csv);
    assert.deepStrictEqual(rec, [['a','b,comma','c']]);
  });
  it('throws on unterminated quote', () => {
    const csv = 'a,"b\n';
    assert.throws(() => parseCsv(csv), /CSV line 1: unterminated quoted field/);
  });
});

describe('CSV export', () => {
  it('exports tasks to CSV', () => {
    const tasks = [
      {id:1,title:'1',priority:'high',status:'open',due:'2026-12-01',tags:['a','b'],notes:'',created:'2026-11-01T00:00:00Z',completed:''},
    ];
    const txt = exportCsv(tasks);
    assert.strictEqual(txt, 'id,title,priority,status,due,tags,notes,created,completed\n1,1,high,open,2026-12-01,a;b,,2026-11-01T00:00:00Z,\n');
  });
});
